<?php

declare(strict_types=1);

namespace Soltec\Kernel;

use InvalidArgumentException;

/**
 * UUID v7 identifiers (ADR-0015): generated by the application so a client could create them offline.
 *
 * Ids are strings with dashes in the application and BINARY(16) in the database. The queries convert with
 * UNHEX() and HEX() so they behave the same on MySQL 5.7 and 8.0 without binary parameter handling.
 */
final class Uuid
{
    private const PATTERN = '/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/';

    /** A time-ordered id, so inserts land at the end of the primary key index. */
    public static function v7(): string
    {
        $milliseconds = (int) floor(microtime(true) * 1000);
        $bytes = substr(pack('J', $milliseconds), 2) . random_bytes(10);
        $bytes[6] = chr((ord($bytes[6]) & 0x0f) | 0x70);
        $bytes[8] = chr((ord($bytes[8]) & 0x3f) | 0x80);

        return self::fromHex(bin2hex($bytes));
    }

    public static function isValid(string $value): bool
    {
        return preg_match(self::PATTERN, $value) === 1;
    }

    /** 32 hexadecimal characters, the argument of UNHEX(). */
    public static function toHex(string $uuid): string
    {
        if (!self::isValid($uuid)) {
            throw new InvalidArgumentException('Not a valid UUID.');
        }

        return str_replace('-', '', $uuid);
    }

    /** Converts the output of LOWER(HEX(id)) back to the dashed form. */
    public static function fromHex(string $hex): string
    {
        if (preg_match('/^[0-9a-f]{32}$/', $hex) !== 1) {
            throw new InvalidArgumentException('Not a valid hexadecimal UUID.');
        }

        return sprintf(
            '%s-%s-%s-%s-%s',
            substr($hex, 0, 8),
            substr($hex, 8, 4),
            substr($hex, 12, 4),
            substr($hex, 16, 4),
            substr($hex, 20),
        );
    }
}
